"""Checks for the Final Assessment coding challenge, Python/FastAPI (intermediate, 20 minutes). Do not edit this file.

Run every check from the assessment folder:  python -m pytest -q
Each check builds a fresh refund store and a stand-in payments service (an httpx mock
transport behind the provided PaymentsClient), plugs both into your app with
dependency overrides, and calls POST /refunds with FastAPI's TestClient.
No real payments service, network or environment variable is used.
"""

import importlib
import sys
from decimal import Decimal
from pathlib import Path

import httpx
import pytest
from fastapi.testclient import TestClient

LAB = Path(__file__).resolve().parent.parent
STARTER = LAB / "starter"
if str(STARTER) not in sys.path:
    sys.path.insert(0, str(STARTER))

from refunds.payments import PaymentsClient  # noqa: E402  (provided, not edited)
from refunds.settings import Settings  # noqa: E402  (provided, not edited)
from refunds.store import RefundStore  # noqa: E402  (provided, not edited)

PAYMENTS = {
    "P100": {"id": "P100", "status": "captured", "amount": 100.00, "customer_email": "dana@example.test"},
    "P250": {"id": "P250", "status": "captured", "amount": 250.50, "customer_email": "lee@example.test"},
    "P300": {"id": "P300", "status": "authorized", "amount": 80.00, "customer_email": "sam@example.test"},
    "P400": {"id": "P400", "status": "voided", "amount": 30.00, "customer_email": "kim@example.test"},
}


class Service:
    """A stand-in payments service: answers from PAYMENTS, or fails the way `mode` says."""

    def __init__(self, mode="ok"):
        self.mode = mode
        self.calls = []

    def __call__(self, request):
        self.calls.append(request.url.path)
        if self.mode == "timeout":
            raise httpx.ReadTimeout("payments service is slow", request=request)
        if self.mode == "refused":
            raise httpx.ConnectError("connection refused", request=request)
        if self.mode == "error":
            return httpx.Response(500, json={"error": "internal"})
        payment = PAYMENTS.get(request.url.path.rsplit("/", 1)[-1])
        if payment is None:
            return httpx.Response(404, json={"error": "not found"})
        return httpx.Response(200, json=payment)


@pytest.fixture
def api(monkeypatch):
    """Yield (client, store, service) wired into your app; clears the overrides afterwards."""
    for name in ("PAYMENTS_BASE_URL", "PAYMENTS_TOKEN", "PAYMENTS_TIMEOUT_SECONDS"):
        monkeypatch.delenv(name, raising=False)
    main = importlib.import_module("refunds.main")
    store = RefundStore()
    service = Service()
    settings = Settings(base_url="http://payments.test", token="test-token")

    def payments_override():
        client = PaymentsClient(settings, transport=httpx.MockTransport(service))
        try:
            yield client
        finally:
            client.close()

    main.app.dependency_overrides[main.get_store] = lambda: store
    main.app.dependency_overrides[main.get_payments] = payments_override
    try:
        yield TestClient(main.app), store, service
    finally:
        main.app.dependency_overrides.clear()


def refund(client, payment_id, amount, reason="Item returned"):
    return client.post("/refunds", json={"payment_id": payment_id, "amount": amount, "reason": reason})


REFUND_OUT_FIELDS = ["amount", "id", "payment_id", "status"]


def accepted(response, what):
    """An accepted refund: a success status, and a body with only the RefundOut fields
    (never the reason or the customer's email). Only check1 insists on 201."""
    assert response.is_success, f"{what} answers a success status, got {response.status_code}"
    assert sorted(response.json()) == REFUND_OUT_FIELDS, (
        f"{what}: the body is exactly the RefundOut fields (id, payment_id, amount, status), "
        "never the reason or the customer_email"
    )
    return response.json()


def stored(store):
    return [(r.id, r.payment_id, r.amount, r.reason, r.customer_email) for r in store.list()]


def test_check1_a_valid_refund_answers_201_with_only_the_refund_fields(api):
    client, store, service = api
    response = refund(client, "P100", "40.00")
    assert response.status_code == 201, "a refund of a captured payment answers 201 Created"
    body = response.json()
    assert sorted(body) == REFUND_OUT_FIELDS, (
        "the body is exactly the RefundOut fields (id, payment_id, amount, status): no reason, no customer_email"
    )
    assert (body["id"], body["payment_id"], Decimal(str(body["amount"])), body["status"]) == (
        "R1", "P100", Decimal("40.00"), "pending",
    ), "the body describes the stored refund"
    assert service.calls == ["/api/payments/P100"], "the route looks the payment up once with the provided client"


def test_check2_the_refund_is_stored_with_the_payment_customer_email(api):
    client, store, _ = api
    accepted(refund(client, "P100", "80.00", reason="Wrong size"), "a refund of P100")
    accepted(refund(client, "P250", "200.00", reason="Damaged box"), "a refund of P250 (P100's refunds do not count)")
    voided = refund(client, "P400", "5", reason="Never arrived")
    assert (voided.status_code, voided.json()) == (409, {"detail": "payment is not captured"}), (
        "P400 is voided, not captured: 409 'payment is not captured', and nothing is stored"
    )
    unknown = refund(client, "P404", "5", reason="No such payment")
    assert (unknown.status_code, unknown.json()) == (404, {"detail": "payment not found"}), (
        "P404 does not exist: 404 'payment not found', and nothing is stored"
    )
    third = accepted(refund(client, "P250", "20", reason="Late delivery"), "a second refund of P250")
    assert third["id"] == "R3", "the refused refunds were not stored, so the third stored refund is R3"
    too_much = refund(client, "P250", "40", reason="Extra")
    assert (too_much.status_code, too_much.json()) == (409, {"detail": "refund exceeds captured amount"}), (
        "P250 (250.50) already has 220.00 refunded: another 40 would exceed it, 409 'refund exceeds captured amount'"
    )
    assert stored(store) == [
        ("R1", "P100", Decimal("80.00"), "Wrong size", "dana@example.test"),
        ("R2", "P250", Decimal("200.00"), "Damaged box", "lee@example.test"),
        ("R3", "P250", Decimal("20"), "Late delivery", "lee@example.test"),
    ], "each accepted refund is added to the store with its reason and its own payment's customer_email"


def test_check3_an_unknown_payment_answers_404_and_stores_nothing(api):
    client, store, _ = api
    response = refund(client, "P404", "5")
    assert (response.status_code, response.json()) == (404, {"detail": "payment not found"}), (
        "PaymentNotFound answers 404 with detail 'payment not found'"
    )
    assert store.list() == [], "a refused refund stores nothing"


def test_check4_a_slow_payments_service_answers_504_and_stores_nothing(api):
    client, store, service = api
    service.mode = "timeout"
    response = refund(client, "P100", "5")
    assert (response.status_code, response.json()) == (504, {"detail": "payments service timed out"}), (
        "UpstreamTimeout answers 504 with detail 'payments service timed out'"
    )
    assert store.list() == [], "a refused refund stores nothing"


def test_check5_a_failing_payments_service_answers_502_and_stores_nothing(api):
    client, store, service = api
    for mode in ("error", "refused"):
        service.mode = mode
        response = refund(client, "P100", "5")
        assert (response.status_code, response.json()) == (502, {"detail": "payments service unavailable"}), (
            f"UpstreamError ({mode}) answers 502 with detail 'payments service unavailable'"
        )
    assert store.list() == [], "a refused refund stores nothing"


def test_check6_a_payment_that_is_not_captured_answers_409(api):
    client, store, _ = api
    for payment_id, amount in (("P300", "5"), ("P300", "500"), ("P400", "5")):
        response = refund(client, payment_id, amount)
        assert (response.status_code, response.json()) == (409, {"detail": "payment is not captured"}), (
            f"{payment_id}'s status is not 'captured', so it answers 409 'payment is not captured', "
            "checked before the amount"
        )
    assert store.list() == [], "a refused refund stores nothing"


def test_check7_earlier_refunds_of_the_same_payment_count_and_other_payments_do_not(api):
    client, store, _ = api
    accepted(refund(client, "P250", "200.00"), "a refund of P250")
    voided = refund(client, "P400", "25.00")
    assert (voided.status_code, voided.json()) == (409, {"detail": "payment is not captured"}), (
        "P400 is voided, not captured: 409 'payment is not captured'"
    )
    accepted(refund(client, "P100", "60.00"), "refunds of P250 do not count against P100: 60.00 of P100's 100.00")
    response = refund(client, "P100", "50.00")
    assert (response.status_code, response.json()) == (409, {"detail": "refund exceeds captured amount"}), (
        "already refunded 60.00 of P100's 100.00: another 50.00 would exceed it and answers 409"
    )
    assert [r.amount for r in store.list("P100")] == [Decimal("60.00")], "a refused refund stores nothing"
    assert len(store.list()) == 2, "the store holds only the two accepted refunds"


def test_check8_refunds_may_add_up_to_exactly_the_captured_amount_but_not_beyond(api):
    client, store, _ = api
    accepted(refund(client, "P250", "200.00"), "a refund of P250")
    accepted(refund(client, "P100", "60.00"), "refunds of P250 do not count against P100: 60.00 of P100's 100.00")
    accepted(refund(client, "P100", "40.00"), "refunds that add up to exactly the captured amount")
    response = refund(client, "P100", "0.01")
    assert (response.status_code, response.json()) == (409, {"detail": "refund exceeds captured amount"}), (
        "once fully refunded, any further refund answers 409 'refund exceeds captured amount'"
    )
    assert [r.amount for r in store.list("P100")] == [Decimal("60.00"), Decimal("40.00")], (
        "the store holds exactly the two accepted refunds of P100"
    )
    assert len(store.list()) == 3, "the store holds only the three accepted refunds"


def test_check9_an_invalid_body_answers_422_without_calling_payments(api):
    client, store, service = api
    for body in (
        {"payment_id": "P100", "amount": "0", "reason": "Zero"},
        {"payment_id": "P100", "amount": "5"},
        {"payment_id": "", "amount": "5", "reason": "Empty id"},
    ):
        response = client.post("/refunds", json=body)
        assert response.status_code == 422, "the body is a RefundRequest, so FastAPI answers 422 for an invalid one"
    assert service.calls == [], "an invalid body is refused before the payments service is called"
    assert store.list() == [], "a refused refund stores nothing"
